insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001621', 'deal with', '/diːl wɪð/', 'phrasal verb', 'lidar com', 'We need to deal with this issue today.', 'Precisamos lidar com essa questão hoje.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001622', 'figure out', '/ˈfɪɡər aʊt/', 'phrasal verb', 'descobrir, entender', 'I finally figured out how the system works.', 'Eu finalmente entendi como o sistema funciona.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001623', 'sort out', '/sɔːrt aʊt/', 'phrasal verb', 'resolver, organizar', 'We sorted out the schedule conflict.', 'Nós resolvemos o conflito de horários.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001624', 'work out', '/wɜːrk aʊt/', 'phrasal verb', 'resolver, dar certo', 'The plan worked out better than expected.', 'O plano deu certo melhor do que esperávamos.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001625', 'iron out', '/ˈaɪərn aʊt/', 'phrasal verb', 'resolver (detalhes)', 'We still need to iron out a few details.', 'Ainda precisamos resolver alguns detalhes.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001626', 'rule out', '/ruːl aʊt/', 'phrasal verb', 'descartar', 'We can''t rule out that option yet.', 'Ainda não podemos descartar essa opção.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001627', 'carry out', '/ˈkæri aʊt/', 'phrasal verb', 'realizar, executar', 'They carried out the plan without any issues.', 'Eles executaram o plano sem nenhum problema.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001628', 'draw up', '/drɔː ʌp/', 'phrasal verb', 'elaborar (documento)', 'The lawyer drew up the contract.', 'O advogado elaborou o contrato.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001629', 'set up', '/set ʌp/', 'phrasal verb', 'estabelecer, montar', 'They set up a new office downtown.', 'Eles montaram um novo escritório no centro.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001630', 'follow up', '/ˈfɒloʊ ʌp/', 'phrasal verb', 'dar continuidade, fazer follow-up', 'I will follow up with the client tomorrow.', 'Vou fazer o follow-up com o cliente amanhã.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001631', 'look into', '/lʊk ˈɪntuː/', 'phrasal verb', 'investigar', 'The team is looking into the complaint.', 'A equipe está investigando a reclamação.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001632', 'narrow down', '/ˈnæroʊ daʊn/', 'phrasal verb', 'restringir, filtrar', 'We narrowed down the list to three candidates.', 'Nós filtramos a lista para três candidatos.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001633', 'bring about', '/brɪŋ əˈbaʊt/', 'phrasal verb', 'causar, provocar', 'The new policy brought about big changes.', 'A nova política provocou grandes mudanças.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001634', 'cut back on', '/kʌt bæk ɒn/', 'phrasal verb', 'reduzir', 'The company cut back on unnecessary expenses.', 'A empresa reduziu gastos desnecessários.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001635', 'lay off', '/leɪ ɒf/', 'phrasal verb', 'demitir (por corte de custos)', 'The factory had to lay off several workers.', 'A fábrica teve que demitir vários funcionários.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001636', 'phase out', '/feɪz aʊt/', 'phrasal verb', 'eliminar gradualmente', 'They are phasing out the old system.', 'Eles estão eliminando o sistema antigo gradualmente.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001637', 'scale back', '/skeɪl bæk/', 'phrasal verb', 'reduzir (escala, tamanho)', 'They scaled back the project due to budget cuts.', 'Eles reduziram o projeto por causa de cortes no orçamento.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001638', 'step down', '/step daʊn/', 'phrasal verb', 'renunciar (a um cargo)', 'The CEO decided to step down after ten years.', 'O CEO decidiu renunciar depois de dez anos.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001639', 'come up with', '/kʌm ʌp wɪð/', 'phrasal verb', 'propor, criar (uma ideia)', 'She came up with a great solution.', 'Ela propôs uma ótima solução.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001640', 'fall through', '/fɔːl θruː/', 'phrasal verb', 'fracassar (um plano)', 'Unfortunately, the deal fell through.', 'Infelizmente, o negócio fracassou.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001641', 'pull off', '/pʊl ɒf/', 'phrasal verb', 'conseguir (algo difícil)', 'They managed to pull off the impossible deadline.', 'Eles conseguiram cumprir o prazo impossível.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001642', 'put off', '/pʊt ɒf/', 'phrasal verb', 'adiar', 'We had to put off the meeting until Monday.', 'Tivemos que adiar a reunião para segunda-feira.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001643', 'break down', '/breɪk daʊn/', 'phrasal verb', 'fracassar (negociação); detalhar', 'The negotiations broke down after two hours.', 'As negociações fracassaram depois de duas horas.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001644', 'touch base', '/tʌtʃ beɪs/', 'phrasal verb', 'entrar em contato rapidamente', 'Let''s touch base again next week.', 'Vamos entrar em contato de novo semana que vem.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001645', 'get around', '/ɡet əˈraʊnd/', 'phrasal verb', 'contornar (um problema)', 'We found a way to get around the restriction.', 'Encontramos uma forma de contornar a restrição.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001646', 'keep up with', '/kiːp ʌp wɪð/', 'phrasal verb', 'manter-se atualizado', 'It is hard to keep up with all the changes.', 'É difícil se manter atualizado com todas as mudanças.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001647', 'take on', '/teɪk ɒn/', 'phrasal verb', 'assumir (responsabilidade)', 'She decided to take on a new project.', 'Ela decidiu assumir um novo projeto.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001648', 'stem from', '/stem frɒm/', 'phrasal verb', 'originar-se de', 'The problem stems from a lack of communication.', 'O problema se origina de uma falta de comunicação.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001649', 'wind down', '/waɪnd daʊn/', 'phrasal verb', 'encerrar gradualmente', 'The company is winding down its old division.', 'A empresa está encerrando gradualmente a divisão antiga.', 'B2', array['phrasal verb']),
('30000000-0000-0000-0000-000000001650', 'account for', '/əˈkaʊnt fɔːr/', 'phrasal verb', 'explicar; representar (uma parcela)', 'Sales account for most of our revenue.', 'As vendas representam a maior parte da nossa receita.', 'B2', array['phrasal verb']);

