('20000000-0000-0000-0000-000000000271', 'fill_blank', 7, '{"sentence": "We still need to ___ a few details.", "options": ["iron out", "rule out", "deal with"], "correct": "iron out", "translation": "Ainda precisamos resolver alguns detalhes."}'),
('20000000-0000-0000-0000-000000000271', 'fill_blank', 8, '{"sentence": "We can''t ___ that option yet.", "options": ["rule out", "figure out", "sort out"], "correct": "rule out", "translation": "Ainda não podemos descartar essa opção."}'),
('20000000-0000-0000-0000-000000000271', 'word_order', 9, '{"words": ["We", "sorted", "out", "the", "schedule", "conflict"], "correct_sentence": "We sorted out the schedule conflict", "translation": "Nós resolvemos o conflito de horários"}'),
('20000000-0000-0000-0000-000000000271', 'word_order', 10, '{"words": ["The", "plan", "worked", "out", "better", "than", "expected"], "correct_sentence": "The plan worked out better than expected", "translation": "O plano deu certo melhor do que esperávamos"}'),
('20000000-0000-0000-0000-000000000271', 'reading', 11, '{"passage": "When problems come up at work, it usually takes several steps to solve them. First, you deal with the most urgent issue. Then, you figure out what caused it and sort out any confusion. Sometimes you need to iron out small details before you can finally rule out further complications.", "translation": "Quando surgem problemas no trabalho, geralmente são necessárias várias etapas para resolvê-los. Primeiro, você lida com a questão mais urgente. Depois, descobre o que causou o problema e organiza qualquer confusão. Às vezes você precisa resolver pequenos detalhes antes de finalmente descartar mais complicações.", "question": "What is the first step mentioned in the text?", "options": ["Ruling out complications", "Dealing with the most urgent issue", "Ironing out details"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000271', 'listening', 12, '{"audio_text": "We need to deal with this issue today. I finally figured out how the system works. We sorted out the schedule conflict.", "question": "What did the speaker figure out, according to the audio?", "options": ["The schedule conflict", "How the system works", "The urgent issue"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000271', 'dictation', 13, '{"audio_text": "We need to deal with this issue today.", "expected": "We need to deal with this issue today."}'),
('20000000-0000-0000-0000-000000000271', 'typing', 14, '{"prompt_pt": "Traduza: ''Nós conseguimos resolver o problema e descartar a pior opção.''", "expected": "We managed to sort out the problem and rule out the worst option.", "ai_review": true}'),

