('20000000-0000-0000-0000-000000000272', 'matching', 6, '{"pairs": [{"left": "carry out", "right": "realizar, executar"}, {"left": "draw up", "right": "elaborar"}, {"left": "set up", "right": "estabelecer, montar"}, {"left": "follow up", "right": "dar continuidade"}, {"left": "look into", "right": "investigar"}, {"left": "narrow down", "right": "restringir, filtrar"}]}'),
('20000000-0000-0000-0000-000000000272', 'fill_blank', 7, '{"sentence": "I will ___ with the client tomorrow.", "options": ["follow up", "carry out", "set up"], "correct": "follow up", "translation": "Vou fazer o follow-up com o cliente amanhã."}'),
