('20000000-0000-0000-0000-000000000272', 'word_order', 9, '{"words": ["They", "carried", "out", "the", "plan", "without", "any", "issues"], "correct_sentence": "They carried out the plan without any issues", "translation": "Eles executaram o plano sem nenhum problema"}'),
('20000000-0000-0000-0000-000000000272', 'word_order', 10, '{"words": ["They", "set", "up", "a", "new", "office", "downtown"], "correct_sentence": "They set up a new office downtown", "translation": "Eles montaram um novo escritório no centro"}'),
('20000000-0000-0000-0000-000000000272', 'reading', 11, '{"passage": "Managing a project usually means drawing up a clear plan, setting up the right team, and carrying it out step by step. When something needs attention, the team looks into the issue and narrows down the possible solutions before following up with everyone involved.", "translation": "Gerenciar um projeto geralmente significa elaborar um plano claro, montar a equipe certa e executá-lo passo a passo. Quando algo precisa de atenção, a equipe investiga a questão e filtra as possíveis soluções antes de fazer o follow-up com todos os envolvidos.", "question": "What does the team do when something needs attention, according to the text?", "options": ["They ignore it", "They look into the issue", "They cancel the project"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000272', 'listening', 12, '{"audio_text": "The lawyer drew up the contract. They set up a new office downtown. The team is looking into the complaint.", "question": "What did the lawyer do, according to the audio?", "options": ["Set up an office", "Drew up the contract", "Looked into a complaint"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000272', 'dictation', 13, '{"audio_text": "They set up a new office downtown.", "expected": "They set up a new office downtown."}'),
('20000000-0000-0000-0000-000000000272', 'typing', 14, '{"prompt_pt": "Traduza: ''Nós vamos investigar o problema e depois fazer o follow-up.''", "expected": "We are going to look into the problem and then follow up.", "ai_review": true}'),

-- Lição 273: Mudanças na empresa (bring about, cut back on, lay off, phase out, scale back, step down)
('20000000-0000-0000-0000-000000000273', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001633", "show_image": false}'),
