('20000000-0000-0000-0000-000000000273', 'multiple_choice', 4, '{"question": "The factory had to ___ several workers.", "audio_text": null, "options": ["lay off", "set up", "carry out"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000273', 'multiple_choice', 5, '{"question": "What does ''step down'' mean?", "audio_text": null, "options": ["Renunciar a um cargo", "Assumir um cargo", "Contratar alguém"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000273', 'matching', 6, '{"pairs": [{"left": "bring about", "right": "causar, provocar"}, {"left": "cut back on", "right": "reduzir"}, {"left": "lay off", "right": "demitir"}, {"left": "phase out", "right": "eliminar gradualmente"}, {"left": "scale back", "right": "reduzir (escala)"}, {"left": "step down", "right": "renunciar"}]}'),
('20000000-0000-0000-0000-000000000273', 'fill_blank', 7, '{"sentence": "The company ___ unnecessary expenses.", "options": ["cut back on", "brought about", "stepped down"], "correct": "cut back on", "translation": "A empresa reduziu gastos desnecessários."}'),
('20000000-0000-0000-0000-000000000273', 'fill_blank', 8, '{"sentence": "They are ___ the old system.", "options": ["phasing out", "laying off", "cutting back on"], "correct": "phasing out", "translation": "Eles estão eliminando o sistema antigo gradualmente."}'),
('20000000-0000-0000-0000-000000000273', 'word_order', 9, '{"words": ["The", "new", "policy", "brought", "about", "big", "changes"], "correct_sentence": "The new policy brought about big changes", "translation": "A nova política provocou grandes mudanças"}'),
('20000000-0000-0000-0000-000000000273', 'word_order', 10, '{"words": ["The", "CEO", "decided", "to", "step", "down", "after", "ten", "years"], "correct_sentence": "The CEO decided to step down after ten years", "translation": "O CEO decidiu renunciar depois de dez anos"}'),
('20000000-0000-0000-0000-000000000273', 'reading', 11, '{"passage": "During difficult times, companies often need to cut back on spending, and in some cases, lay off employees. Old systems may be phased out, and entire projects can be scaled back. Even leaders sometimes step down when a big change is needed, hoping to bring about a fresh start.", "translation": "Em tempos difíceis, as empresas frequentemente precisam reduzir gastos e, em alguns casos, demitir funcionários. Sistemas antigos podem ser eliminados gradualmente, e projetos inteiros podem ser reduzidos. Até líderes às vezes renunciam quando uma grande mudança é necessária, na esperança de provocar um novo começo.", "question": "What may happen to old systems, according to the text?", "options": ["They are expanded", "They are phased out", "They are ignored"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000273', 'listening', 12, '{"audio_text": "The factory had to lay off several workers. They are phasing out the old system. The CEO decided to step down.", "question": "What did the factory have to do, according to the audio?", "options": ["Lay off workers", "Hire more workers", "Expand the system"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000273', 'dictation', 13, '{"audio_text": "The factory had to lay off several workers.", "expected": "The factory had to lay off several workers."}'),
('20000000-0000-0000-0000-000000000273', 'typing', 14, '{"prompt_pt": "Traduza: ''A empresa reduziu gastos e teve que demitir alguns funcionários.''", "expected": "The company cut back on expenses and had to lay off some employees.", "ai_review": true}'),

