('20000000-0000-0000-0000-000000000274', 'word_order', 9, '{"words": ["She", "came", "up", "with", "a", "great", "solution"], "correct_sentence": "She came up with a great solution", "translation": "Ela propôs uma ótima solução"}'),
('20000000-0000-0000-0000-000000000274', 'word_order', 10, '{"words": ["Let''s", "touch", "base", "again", "next", "week"], "correct_sentence": "Let''s touch base again next week", "translation": "Vamos entrar em contato de novo semana que vem"}'),
('20000000-0000-0000-0000-000000000274', 'reading', 11, '{"passage": "During tough negotiations, the two sides tried to come up with a fair agreement, but the talks eventually broke down. What seemed like a great deal fell through at the last minute, so both teams decided to touch base again the following week and put off the final decision.", "translation": "Durante negociações difíceis, os dois lados tentaram propor um acordo justo, mas as conversas acabaram fracassando. O que parecia um ótimo negócio fracassou de última hora, então as duas equipes decidiram entrar em contato de novo na semana seguinte e adiar a decisão final.", "question": "What happened to the negotiations, according to the text?", "options": ["They succeeded quickly", "They eventually broke down", "They were never scheduled"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000274', 'listening', 12, '{"audio_text": "She came up with a great solution. Unfortunately, the deal fell through. Let''s touch base again next week.", "question": "What happened to the deal, according to the audio?", "options": ["It succeeded", "It fell through", "It was postponed"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000274', 'dictation', 13, '{"audio_text": "Unfortunately, the deal fell through.", "expected": "Unfortunately, the deal fell through."}'),
